// Package seed provides the bundled starter product database. products.csv is
// generated by ./gen from USDA FoodData Central (SR Legacy, CC0 1.0) data.
package seed

import (
	_ "embed"
	"encoding/csv"
	"fmt"
	"strconv"
	"strings"

	"mealplan/internal/domain"
	"mealplan/internal/units"
)

//go:embed products.csv
var productsCSV string

// Products returns the bundled products without ID and household.
func Products() ([]domain.Product, error) {
	r := csv.NewReader(strings.NewReader(productsCSV))
	r.Comma = ';'
	r.Comment = '#'
	rows, err := r.ReadAll()
	if err != nil {
		return nil, fmt.Errorf("seed products.csv: %w", err)
	}
	if len(rows) == 0 || strings.Join(rows[0], ";") != "name;aliases;kcal;protein;carbs;fat;piece_grams;density_g_ml" {
		return nil, fmt.Errorf("seed products.csv: unexpected header")
	}
	out := make([]domain.Product, 0, len(rows)-1)
	for i, row := range rows[1:] {
		line := i + 2
		if len(row) != 8 {
			return nil, fmt.Errorf("seed products.csv row %d: want 8 columns, got %d", line, len(row))
		}
		p := domain.Product{Name: row[0], NormalizedName: units.NormalizeName(row[0])}
		for _, a := range strings.Split(row[1], "|") {
			if a != "" {
				p.Aliases = append(p.Aliases, units.NormalizeName(a))
			}
		}
		for j, dst := range []**float64{&p.Per100g.Kcal, &p.Per100g.Protein, &p.Per100g.Carbs, &p.Per100g.Fat, &p.PieceGrams, &p.DensityGPerML} {
			cell := row[2+j]
			if cell == "" {
				if j < 4 {
					return nil, fmt.Errorf("seed products.csv row %d (%s): missing macro column %d", line, row[0], j+3)
				}
				continue
			}
			v, err := strconv.ParseFloat(cell, 64)
			if err != nil {
				return nil, fmt.Errorf("seed products.csv row %d (%s): %w", line, row[0], err)
			}
			*dst = &v
		}
		out = append(out, p)
	}
	return out, nil
}
